#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SocialMessagingError {
    NotFound,
    Conflict,
    RateLimited(i64),
    Database(String),
}

impl From<rusqlite::Error> for SocialMessagingError {
    fn from(error: rusqlite::Error) -> Self {
        Self::Database(error.to_string())
    }
}

