    /// Keyset-paginated search posts (FTS5 when available, LIKE fallback).
    pub fn social_search_posts_keyset(
        &self,
        query: &str,
        limit: i64,
        cursor_created_at: Option<&str>,
        cursor_id: Option<&str>,
        blocked_ids: &[String],
        muted_ids: &[String],
    ) -> Vec<serde_json::Value> {
        let _t = std::time::Instant::now();
        let conn = self.conn();
        let pattern = format!("%{query}%");
        let fts_q = sanitize_fts_query(query);
        let excluded: Vec<String> = blocked_ids
            .iter()
            .chain(muted_ids.iter())
            .cloned()
            .collect();
        let map_row = |row: &rusqlite::Row| -> rusqlite::Result<serde_json::Value> {
            let agent_name: Option<String> = row.get(13)?;
            Ok(serde_json::json!({
                "id": row.get::<_, String>(0)?,
                "body": row.get::<_, String>(3)?,
                "visibility": row.get::<_, String>(4)?,
                "proofState": row.get::<_, String>(5)?,
                "authorMode": row.get::<_, String>(6)?,
                "replyToPostId": row.get::<_, Option<String>>(7)?,
                "quotePostId": row.get::<_, Option<String>>(8)?,
                "createdAt": row.get::<_, String>(9)?,
                "updatedAt": row.get::<_, String>(10)?,
                "author": {
                    "profileId": row.get::<_, String>(1)?,
                    "handle": row.get::<_, String>(11)?,
                    "displayName": row.get::<_, String>(12)?,
                },
                "linkedAgent": if agent_name.is_some() {
                    serde_json::json!({
                        "id": row.get::<_, Option<String>>(2)?,
                        "agentName": agent_name,
                        "agentSlug": row.get::<_, Option<String>>(14)?,
                    })
                } else { serde_json::Value::Null },
            }))
        };
        let exclude_clause = if excluded.is_empty() {
            String::new()
        } else {
            let start = if cursor_created_at.is_some() { 5 } else { 3 };
            let ph: Vec<String> = (0..excluded.len())
                .map(|i| format!("?{}", start + i))
                .collect();
            format!("AND sp.profile_id NOT IN ({})", ph.join(", "))
        };

        // Prefer FTS5 MATCH when virtual table + usable query tokens exist.
        let fts_rows: Option<Vec<serde_json::Value>> = if let Some(ref match_q) = fts_q {
            let has_fts: bool = conn
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE name='social_posts_fts'",
                    [],
                    |r| r.get::<_, i64>(0),
                )
                .unwrap_or(0)
                > 0;
            if !has_fts {
                None
            } else if cursor_created_at.is_some() && cursor_id.is_some() {
                let sql = format!(
                    "SELECT sp.id, sp.profile_id, sp.linked_agent_id, sp.body, sp.visibility,
                            sp.proof_state, sp.author_mode, sp.reply_to_post_id, sp.quote_post_id,
                            sp.created_at, sp.updated_at, p.handle, p.display_name,
                            la.agent_name, la.agent_slug
                     FROM social_posts_fts fts
                     JOIN social_posts sp ON sp.id = fts.post_id
                     JOIN social_profiles p ON p.id = sp.profile_id
                     LEFT JOIN social_linked_agents la ON la.id = sp.linked_agent_id
                     WHERE social_posts_fts MATCH ?1
                       AND sp.visibility = 'public' AND sp.deleted_at IS NULL
                       AND (sp.created_at < ?2 OR (sp.created_at = ?2 AND sp.id < ?3))
                       {exclude_clause}
                     ORDER BY sp.created_at DESC, sp.id DESC LIMIT ?4"
                );
                match conn.prepare(&sql) {
                    Ok(mut stmt) => {
                        let result = if excluded.is_empty() {
                            stmt.query_map(
                                params![
                                    match_q,
                                    cursor_created_at.unwrap(),
                                    cursor_id.unwrap(),
                                    limit
                                ],
                                map_row,
                            )
                            .map(|rows| rows.filter_map(|r| r.ok()).collect())
                        } else {
                            let mut p: Vec<Box<dyn rusqlite::types::ToSql>> = vec![
                                Box::new(match_q.clone()),
                                Box::new(cursor_created_at.unwrap().to_string()),
                                Box::new(cursor_id.unwrap().to_string()),
                                Box::new(limit),
                            ];
                            for id in &excluded {
                                p.push(Box::new(id.clone()));
                            }
                            let pr: Vec<&dyn rusqlite::types::ToSql> =
                                p.iter().map(|b| b.as_ref()).collect();
                            stmt.query_map(pr.as_slice(), map_row)
                                .map(|rows| rows.filter_map(|r| r.ok()).collect())
                        };
                        result.ok()
                    }
                    Err(e) => {
                        tracing::warn!(error = %e, "FTS search prepare failed — falling back to LIKE");
                        None
                    }
                }
            } else {
                let sql = format!(
                    "SELECT sp.id, sp.profile_id, sp.linked_agent_id, sp.body, sp.visibility,
                            sp.proof_state, sp.author_mode, sp.reply_to_post_id, sp.quote_post_id,
                            sp.created_at, sp.updated_at, p.handle, p.display_name,
                            la.agent_name, la.agent_slug
                     FROM social_posts_fts fts
                     JOIN social_posts sp ON sp.id = fts.post_id
                     JOIN social_profiles p ON p.id = sp.profile_id
                     LEFT JOIN social_linked_agents la ON la.id = sp.linked_agent_id
                     WHERE social_posts_fts MATCH ?1
                       AND sp.visibility = 'public' AND sp.deleted_at IS NULL
                       {exclude_clause}
                     ORDER BY sp.created_at DESC, sp.id DESC LIMIT ?2"
                );
                match conn.prepare(&sql) {
                    Ok(mut stmt) => {
                        let result = if excluded.is_empty() {
                            stmt.query_map(params![match_q, limit], map_row)
                                .map(|rows| rows.filter_map(|r| r.ok()).collect())
                        } else {
                            let mut p: Vec<Box<dyn rusqlite::types::ToSql>> =
                                vec![Box::new(match_q.clone()), Box::new(limit)];
                            for id in &excluded {
                                p.push(Box::new(id.clone()));
                            }
                            let pr: Vec<&dyn rusqlite::types::ToSql> =
                                p.iter().map(|b| b.as_ref()).collect();
                            stmt.query_map(pr.as_slice(), map_row)
                                .map(|rows| rows.filter_map(|r| r.ok()).collect())
                        };
                        result.ok()
                    }
                    Err(e) => {
                        tracing::warn!(error = %e, "FTS search prepare failed — falling back to LIKE");
                        None
                    }
                }
            }
        } else {
            None
        };

        let rows: Vec<serde_json::Value> = if let Some(rows) = fts_rows {
            tracing::info!(
                method = "social_search_posts_keyset",
                engine = "fts5",
                duration_ms = _t.elapsed().as_millis(),
                row_count = rows.len(),
                "db query"
            );
            return rows;
        } else if cursor_created_at.is_some() && cursor_id.is_some() {
            let sql = format!(
                "SELECT sp.id, sp.profile_id, sp.linked_agent_id, sp.body, sp.visibility,
                        sp.proof_state, sp.author_mode, sp.reply_to_post_id, sp.quote_post_id,
                        sp.created_at, sp.updated_at, p.handle, p.display_name,
                        la.agent_name, la.agent_slug
                 FROM social_posts sp
                 JOIN social_profiles p ON p.id = sp.profile_id
                 LEFT JOIN social_linked_agents la ON la.id = sp.linked_agent_id
                 WHERE sp.visibility = 'public' AND sp.deleted_at IS NULL AND sp.body LIKE ?1
                   AND (sp.created_at < ?2 OR (sp.created_at = ?2 AND sp.id < ?3))
                   {exclude_clause}
                 ORDER BY sp.created_at DESC, sp.id DESC LIMIT ?4"
            );
            let mut stmt = conn.prepare(&sql).unwrap();
            if excluded.is_empty() {
                stmt.query_map(
                    params![
                        pattern,
                        cursor_created_at.unwrap(),
                        cursor_id.unwrap(),
                        limit
                    ],
                    map_row,
                )
                .unwrap()
                .filter_map(|r| r.ok())
                .collect()
            } else {
                let mut p: Vec<Box<dyn rusqlite::types::ToSql>> = vec![
                    Box::new(pattern.clone()),
                    Box::new(cursor_created_at.unwrap().to_string()),
                    Box::new(cursor_id.unwrap().to_string()),
                    Box::new(limit),
                ];
                for id in &excluded {
                    p.push(Box::new(id.clone()));
                }
                let pr: Vec<&dyn rusqlite::types::ToSql> = p.iter().map(|b| b.as_ref()).collect();
                stmt.query_map(pr.as_slice(), map_row)
                    .unwrap()
                    .filter_map(|r| r.ok())
                    .collect()
            }
        } else {
            let sql = format!(
                "SELECT sp.id, sp.profile_id, sp.linked_agent_id, sp.body, sp.visibility,
                        sp.proof_state, sp.author_mode, sp.reply_to_post_id, sp.quote_post_id,
                        sp.created_at, sp.updated_at, p.handle, p.display_name,
                        la.agent_name, la.agent_slug
                 FROM social_posts sp
                 JOIN social_profiles p ON p.id = sp.profile_id
                 LEFT JOIN social_linked_agents la ON la.id = sp.linked_agent_id
                 WHERE sp.visibility = 'public' AND sp.deleted_at IS NULL AND sp.body LIKE ?1
                   {exclude_clause}
                 ORDER BY sp.created_at DESC, sp.id DESC LIMIT ?2"
            );
            let mut stmt = conn.prepare(&sql).unwrap();
            if excluded.is_empty() {
                stmt.query_map(params![pattern, limit], map_row)
                    .unwrap()
                    .filter_map(|r| r.ok())
                    .collect()
            } else {
                let mut p: Vec<Box<dyn rusqlite::types::ToSql>> =
                    vec![Box::new(pattern.clone()), Box::new(limit)];
                for id in &excluded {
                    p.push(Box::new(id.clone()));
                }
                let pr: Vec<&dyn rusqlite::types::ToSql> = p.iter().map(|b| b.as_ref()).collect();
                stmt.query_map(pr.as_slice(), map_row)
                    .unwrap()
                    .filter_map(|r| r.ok())
                    .collect()
            }
        };
        tracing::info!(
            method = "social_search_posts_keyset",
            engine = "like",
            duration_ms = _t.elapsed().as_millis(),
            row_count = rows.len(),
            "db query"
        );
        rows
    }

    // ─── Wave 4: Media uploads ─────────────────────────────────────────────────

    /// Create a media object in pending status, generating a storage key.
    pub fn social_create_media_object(
        &self,
        owner_profile_id: &str,
        filename: &str,
        content_type: &str,
        size_bytes: i64,
        media_type: &str,
    ) -> serde_json::Value {
        let conn = self.conn();
        let id = format!("media_{}", Uuid::new_v4());
        // Storage key: media/{profile_id}/{media_id}/{filename}
        let storage_key = format!("media/{}/{}/{}", owner_profile_id, id, filename);
        conn.execute(
            "INSERT INTO social_media_objects (id, owner_profile_id, filename, content_type, size_bytes, media_type, storage_key, status)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 'pending')",
            params![id, owner_profile_id, filename, content_type, size_bytes, media_type, storage_key],
        ).expect("insert media object");
        serde_json::json!({
            "id": id,
            "ownerProfileId": owner_profile_id,
            "filename": filename,
            "contentType": content_type,
            "sizeBytes": size_bytes,
            "mediaType": media_type,
            "storageKey": storage_key,
            "status": "pending",
        })
    }

    /// Finalize a media object (mark as "ready").
    pub fn social_finalize_media_object(&self, media_id: &str) -> serde_json::Value {
        let conn = self.conn();
        conn.execute(
            "UPDATE social_media_objects SET status = 'ready', updated_at = datetime('now') WHERE id = ?1",
            params![media_id],
        ).expect("finalize media object");
        let mut stmt = conn.prepare(
            "SELECT id, owner_profile_id, filename, content_type, size_bytes, media_type, storage_key, status, created_at, updated_at
             FROM social_media_objects WHERE id = ?1"
        ).unwrap();
        stmt.query_row([media_id], |row| {
            Ok(serde_json::json!({
                "id": row.get::<_, String>(0)?,
                "ownerProfileId": row.get::<_, String>(1)?,
                "filename": row.get::<_, String>(2)?,
                "contentType": row.get::<_, String>(3)?,
                "sizeBytes": row.get::<_, i64>(4)?,
                "mediaType": row.get::<_, String>(5)?,
                "storageKey": row.get::<_, String>(6)?,
                "status": row.get::<_, String>(7)?,
                "createdAt": row.get::<_, String>(8)?,
                "updatedAt": row.get::<_, String>(9)?,
            }))
        })
        .unwrap()
    }

    /// Get a media object by ID.
    pub fn social_get_media_object(&self, media_id: &str) -> Option<serde_json::Value> {
        let conn = self.conn();
        let mut stmt = conn.prepare(
            "SELECT id, owner_profile_id, filename, content_type, size_bytes, media_type, storage_key, status, created_at, updated_at
             FROM social_media_objects WHERE id = ?1"
        ).unwrap();
        stmt.query_row([media_id], |row| {
            Ok(serde_json::json!({
                "id": row.get::<_, String>(0)?,
                "ownerProfileId": row.get::<_, String>(1)?,
                "filename": row.get::<_, String>(2)?,
                "contentType": row.get::<_, String>(3)?,
                "sizeBytes": row.get::<_, i64>(4)?,
                "mediaType": row.get::<_, String>(5)?,
                "storageKey": row.get::<_, String>(6)?,
                "status": row.get::<_, String>(7)?,
                "createdAt": row.get::<_, String>(8)?,
                "updatedAt": row.get::<_, String>(9)?,
            }))
        })
        .ok()
    }

    /// Link media objects to a post. Only links media that is owned by the given profile
    /// and in "ready" status.
    pub fn social_link_media_to_post(
        &self,
        post_id: &str,
        media_ids: &[String],
        owner_profile_id: &str,
    ) -> Vec<String> {
        let conn = self.conn();
        let mut linked = Vec::new();
        for (position, media_id) in media_ids.iter().enumerate() {
            // Verify ownership and ready status
            let owned: bool = conn.query_row(
                "SELECT COUNT(*) > 0 FROM social_media_objects WHERE id = ?1 AND owner_profile_id = ?2 AND status = 'ready'",
                params![media_id, owner_profile_id],
                |row| row.get(0),
            ).unwrap_or(false);
            if owned {
                conn.execute(
                    "INSERT OR IGNORE INTO social_post_media (post_id, media_id, position) VALUES (?1, ?2, ?3)",
                    params![post_id, media_id, position as i64],
                ).ok();
                // Mark media as "attached"
                conn.execute(
                    "UPDATE social_media_objects SET status = 'attached', updated_at = datetime('now') WHERE id = ?1",
                    params![media_id],
                ).ok();
                linked.push(media_id.clone());
            }
        }
        linked
    }

    pub fn social_get_media_delivery_context(
        &self,
        media_id: &str,
    ) -> Option<(String, String, String, String)> {
        let conn = self.conn();
        conn.query_row(
            "SELECT owner_profile_id, storage_key, content_type, status
               FROM social_media_objects WHERE id = ?1",
            [media_id],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                ))
            },
        )
        .ok()
    }

    pub fn social_media_is_attached_to_post(&self, media_id: &str, post_id: &str) -> bool {
        let conn = self.conn();
        conn.query_row(
            "SELECT EXISTS(
                SELECT 1 FROM social_post_media
                 WHERE media_id = ?1 AND post_id = ?2
            )",
            params![media_id, post_id],
            |row| row.get::<_, bool>(0),
        )
        .unwrap_or(false)
    }

    /// Get media objects attached to a post.
    pub fn social_get_post_media(
        &self,
        post_id: &str,
        viewer_profile_id: Option<&str>,
    ) -> Vec<serde_json::Value> {
        let conn = self.conn();
        let mut stmt = conn.prepare(
            "SELECT m.id, m.filename, m.content_type, m.size_bytes, m.media_type, m.storage_key, pm.position
             FROM social_media_objects m
             JOIN social_post_media pm ON pm.media_id = m.id
             WHERE pm.post_id = ?1
             ORDER BY pm.position ASC"
        ).unwrap();
        stmt.query_map(params![post_id], |row| {
            let media_id: String = row.get(0)?;
            let delivery_url = crate::media::signed_media_delivery_url(
                &media_id,
                Some(post_id),
                viewer_profile_id,
            );
            Ok(serde_json::json!({
                "id": media_id,
                "filename": row.get::<_, String>(1)?,
                "contentType": row.get::<_, String>(2)?,
                "sizeBytes": row.get::<_, i64>(3)?,
                "mediaType": row.get::<_, String>(4)?,
                "url": delivery_url,
                "position": row.get::<_, i64>(6)?,
            }))
        })
        .unwrap()
        .filter_map(|r| r.ok())
        .collect()
    }

    /// Find orphaned media objects (pending for more than 1 hour) eligible for cleanup.
    pub fn social_get_orphaned_media(&self, limit: i64) -> Vec<serde_json::Value> {
        let conn = self.conn();
        let mut stmt = conn
            .prepare(
            "SELECT id, owner_profile_id, storage_key, created_at
             FROM social_media_objects
             WHERE status = 'pending'
               AND created_at < datetime('now', '-1 hour')
             ORDER BY created_at ASC
             LIMIT ?1",
            )
            .unwrap();
        stmt.query_map(params![limit], |row| {
            Ok(serde_json::json!({
                "id": row.get::<_, String>(0)?,
                "ownerProfileId": row.get::<_, String>(1)?,
                "storageKey": row.get::<_, String>(2)?,
                "createdAt": row.get::<_, String>(3)?,
            }))
        })
        .unwrap()
        .filter_map(|r| r.ok())
        .collect()
    }

    /// Delete orphaned media objects by IDs (mark as "deleted").
    pub fn social_delete_orphaned_media(&self, media_ids: &[String]) -> usize {
        let conn = self.conn();
        let mut count = 0;
        for id in media_ids {
            let updated = conn.execute(
                "UPDATE social_media_objects SET status = 'deleted', updated_at = datetime('now')
                 WHERE id = ?1 AND status = 'pending'",
                params![id],
            ).unwrap_or(0);
            count += updated;
        }
        count
    }

    // --- Community membership ---

    /// Join a community as `member` (insert membership row; no-op if already a member).
    pub fn social_join_community(&self, community_id: &str, profile_id: &str) -> bool {
        let conn = self.conn();
        let id = format!("cmem_{}", Uuid::new_v4());
        let inserted = conn.execute(
            "INSERT OR IGNORE INTO social_community_memberships (id, community_id, profile_id, role)
             VALUES (?1, ?2, ?3, 'member')",
            params![id, community_id, profile_id],
        ).unwrap_or(0);
        inserted > 0
    }

    /// Leave a community (delete membership row).
    pub fn social_leave_community(&self, community_id: &str, profile_id: &str) -> bool {
        let conn = self.conn();
        let deleted = conn
            .execute(
            "DELETE FROM social_community_memberships
             WHERE community_id = ?1 AND profile_id = ?2",
            params![community_id, profile_id],
            )
            .unwrap_or(0);
        deleted > 0
    }

    /// List members of a community, most-recently-joined first (includes role).
    pub fn social_list_community_members(
        &self,
        community_id: &str,
        limit: i64,
    ) -> Vec<serde_json::Value> {
        let conn = self.conn();
        let mut stmt = conn
            .prepare(
            "SELECT p.id, p.handle, p.display_name, p.avatar_url, m.joined_at,
                    COALESCE(m.role, 'member')
             FROM social_community_memberships m
             JOIN social_profiles p ON p.id = m.profile_id
             WHERE m.community_id = ?1
             ORDER BY CASE COALESCE(m.role, 'member') WHEN 'owner' THEN 0 ELSE 1 END,
                      m.joined_at DESC
             LIMIT ?2",
            )
            .unwrap();
        stmt.query_map(params![community_id, limit], |row| {
            Ok(serde_json::json!({
                "profileId": row.get::<_, String>(0)?,
                "handle": row.get::<_, String>(1)?,
                "displayName": row.get::<_, String>(2)?,
                "avatarUrl": row.get::<_, Option<String>>(3)?,
                "joinedAt": row.get::<_, String>(4)?,
                "role": row.get::<_, String>(5)?,
            }))
        })
        .unwrap()
        .filter_map(|r| r.ok())
        .collect()
    }

    /// Check whether a profile is a member of a community.
    pub fn social_is_community_member(&self, community_id: &str, profile_id: &str) -> bool {
        let conn = self.conn();
        conn.query_row(
            "SELECT 1 FROM social_community_memberships
             WHERE community_id = ?1 AND profile_id = ?2",
            params![community_id, profile_id],
            |_| Ok(()),
        )
        .is_ok()
    }

    // --- Community invites (Batch C) ---

    /// Create a private-guild invite. Stores `token_hash` only (plaintext is caller-held once).
    /// `max_uses`: None = unlimited. `expires_at`: ISO-ish SQLite datetime string or None.
    pub fn social_create_community_invite(
        &self,
        community_id: &str,
        created_by_profile_id: &str,
        token_hash: &str,
        max_uses: Option<i64>,
        expires_at: Option<&str>,
    ) -> Result<serde_json::Value, String> {
        let conn = self.conn();
        let id = format!("cinv_{}", Uuid::new_v4());
        conn.execute(
            "INSERT INTO social_community_invites
             (id, community_id, created_by_profile_id, token_hash, max_uses, use_count, expires_at)
             VALUES (?1, ?2, ?3, ?4, ?5, 0, ?6)",
            params![
                id,
                community_id,
                created_by_profile_id,
                token_hash,
                max_uses,
                expires_at
            ],
        )
        .map_err(|e| format!("create invite failed: {e}"))?;
        drop(conn);
        self.social_get_community_invite_by_id(&id)
            .ok_or_else(|| "invite created but not found".into())
    }

    pub fn social_get_community_invite_by_id(&self, invite_id: &str) -> Option<serde_json::Value> {
        let conn = self.conn();
        conn.query_row(
            "SELECT id, community_id, created_by_profile_id, max_uses, use_count,
                    expires_at, revoked_at, created_at
             FROM social_community_invites WHERE id = ?1",
            [invite_id],
            |row| {
                Ok(serde_json::json!({
                    "id": row.get::<_, String>(0)?,
                    "communityId": row.get::<_, String>(1)?,
                    "createdByProfileId": row.get::<_, String>(2)?,
                    "maxUses": row.get::<_, Option<i64>>(3)?,
                    "useCount": row.get::<_, i64>(4)?,
                    "expiresAt": row.get::<_, Option<String>>(5)?,
                    "revokedAt": row.get::<_, Option<String>>(6)?,
                    "createdAt": row.get::<_, String>(7)?,
                }))
            },
        )
        .ok()
    }

