    /// Publish due schedules: returns list of {scheduleId, postId, draftId}.
    pub fn pulse_process_due_schedules(&self, now_iso: &str) -> Vec<serde_json::Value> {
        let due: Vec<(String, String, String)> = {
            let conn = self.conn();
            let mut stmt = conn
                .prepare(
                    "SELECT id, profile_id, draft_id FROM pulse_schedules
                     WHERE status = 'scheduled' AND publish_at <= ?1",
                )
                .unwrap();
            stmt.query_map(params![now_iso], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .unwrap()
            .filter_map(|r| r.ok())
            .collect()
        };

        let mut results = Vec::new();
        for (sched_id, profile_id, draft_id) in due {
            let draft = match self.pulse_get_draft(&draft_id, &profile_id) {
                Some(d) if d["status"].as_str() == Some("approved") => d,
                _ => {
                    let conn = self.conn();
                    let _ = conn.execute(
                        "UPDATE pulse_schedules SET status = 'failed', updated_at = ?1 WHERE id = ?2",
                        params![now_iso, sched_id],
                    );
                    continue;
                }
            };
            // CAS first so concurrent HTTP publish cannot double-post the same draft.
            let body = draft["body"].as_str().unwrap_or("").to_string();
            let visibility = draft["visibility"].as_str().unwrap_or("public").to_string();
            let author_mode = draft["authorMode"].as_str().unwrap_or("person").to_string();
            let linked = draft["linkedAgentId"].as_str().map(|s| s.to_string());
            if self
                .pulse_cas_update_draft_status(&draft_id, &profile_id, &["approved"], "published")
                .is_none()
            {
                let conn = self.conn();
                let _ = conn.execute(
                    "UPDATE pulse_schedules SET status = 'failed', updated_at = ?1 WHERE id = ?2",
                    params![now_iso, sched_id],
                );
                continue;
            }
            let post = self.social_create_post(
                &profile_id,
                &body,
                &visibility,
                &author_mode,
                linked.as_deref(),
                None,
                None,
                None,
            );
            let post_id = post["id"].as_str().unwrap_or("").to_string();
            self.pulse_add_audit(
                &draft_id,
                &profile_id,
                "scheduled_publish",
                Some(&serde_json::json!({ "postId": post_id, "scheduleId": sched_id }).to_string()),
            );
            {
                let conn = self.conn();
                let _ = conn.execute(
                    "UPDATE pulse_schedules SET status = 'published', updated_at = ?1 WHERE id = ?2",
                    params![now_iso, sched_id],
                );
            }
            results.push(serde_json::json!({
                "scheduleId": sched_id,
                "draftId": draft_id,
                "postId": post_id,
            }));
        }
        results
    }

    // --- API key management ---

    pub fn upsert_api_key(&self, user_id: &str, provider: &str, encrypted_key: &str) {
        let conn = self.conn();
        let id = Uuid::new_v4().to_string();
        conn.execute(
            "INSERT INTO user_api_keys (id, user_id, provider, encrypted_key)
             VALUES (?1, ?2, ?3, ?4)
             ON CONFLICT(user_id, provider) DO UPDATE SET encrypted_key = excluded.encrypted_key",
            params![id, user_id, provider, encrypted_key],
        )
        .expect("upsert_api_key failed");
    }

    pub fn get_api_key(&self, user_id: &str, provider: &str) -> Option<String> {
        let conn = self.conn();
        conn.query_row(
            "SELECT encrypted_key FROM user_api_keys WHERE user_id = ?1 AND provider = ?2",
            params![user_id, provider],
            |row| row.get(0),
        )
        .ok()
    }

    pub fn get_any_api_key(&self, user_id: &str) -> Option<(String, String)> {
        let conn = self.conn();
        conn.query_row(
            "SELECT provider, encrypted_key FROM user_api_keys WHERE user_id = ?1 ORDER BY created_at DESC LIMIT 1",
            params![user_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        ).ok()
    }

    pub fn list_api_keys(&self, user_id: &str) -> Vec<UserApiKeyInfo> {
        let conn = self.conn();
        let mut stmt = conn.prepare(
            "SELECT provider, created_at, encrypted_key FROM user_api_keys WHERE user_id = ?1 ORDER BY provider"
        ).expect("list_api_keys prepare failed");
        stmt.query_map(params![user_id], |row| {
            let encrypted: String = row.get(2)?;
            let prefix = match crate::crypto::decrypt(&encrypted) {
                Ok(plain) if plain.len() >= 8 => format!("{}...", &plain[..8]),
                Ok(plain) if !plain.is_empty() => format!("{}...", &plain[..1]),
                _ => "****".to_string(),
            };
            Ok(UserApiKeyInfo {
                provider: row.get(0)?,
                created_at: row.get(1)?,
                key_prefix: prefix,
            })
        })
        .unwrap()
        .filter_map(|r| r.ok())
        .collect()
    }

    pub fn delete_api_key(&self, user_id: &str, provider: &str) -> bool {
        let conn = self.conn();
        let count = conn
            .execute(
            "DELETE FROM user_api_keys WHERE user_id = ?1 AND provider = ?2",
            params![user_id, provider],
            )
            .unwrap_or(0);
        count > 0
    }

