        db.social_update_profile_prefs(
            owner_id,
            None,
            None,
            Some(true),
            None,
            Some("followers"),
            None,
            None,
        );
        assert_eq!(
            db.social_authorize_profile(owner_id, Some(viewer_id), ProfileAction::View),
            PolicyDecision::Conceal
        );
        db.social_follow(viewer_id, owner_id);
        assert_eq!(
            db.social_authorize_profile(owner_id, Some(viewer_id), ProfileAction::View),
            PolicyDecision::Allow
        );
