    #[test]
    fn get_group_operations_summary_counts_evidence_gated_done() {
        let db = test_db();
        db.upsert_group_task_state(
            "user-1",
            "group-1",
            &task_state_with_tasks(serde_json::json!([
                {
                    "id": "task-verified",
                    "groupId": "group-1",
                    "title": "Verified done task",
                    "status": "done",
                    "priority": "normal",
                    "assigneeId": "user-1",
                    "createdAt": "2026-05-25T00:00:00Z",
                    "updatedAt": "2026-05-25T00:00:00Z",
                    "createdBy": "You"
                },
                {
                    "id": "task-raw",
                    "groupId": "group-1",
                    "title": "Raw done task",
                    "status": "done",
                    "priority": "normal",
                    "assigneeId": "user-1",
                    "createdAt": "2026-05-25T00:00:00Z",
                    "updatedAt": "2026-05-25T00:00:00Z",
                    "createdBy": "You"
                }
            ])),
        );
        let run_id = db.create_run_with_metadata(
            "user-1",
            "Ship verified done task",
            "auto",
            &[],
            Some("task-verified"),
            Some("group-1"),
            None,
        );
        let step_id = db.create_step(&run_id, "implement", "standard", "medium", "Ship it");
        {
            let conn = db.conn();
            conn.execute(
                "UPDATE steps
                 SET status = 'verified'
                 WHERE id = ?1",
                params![step_id],
            )
            .unwrap();
        }
        db.record_verifier_report(
            &step_id,
            &run_id,
            0,
            None,
            "test",
            "verified",
            "pass",
            r#"{"verifier_report":{"verdict":"success"}}"#,
        );
        assert!(db.update_run_status(&run_id, "succeeded", None));

        let summary = db.get_group_operations_summary("user-1", "group-1", 25);

        assert_eq!(summary["tasks"]["done_raw"], 2);
        assert_eq!(summary["tasks"]["completion"]["gated_done_available"], true);
        assert_eq!(summary["tasks"]["completion"]["gated_done"], 1);
        assert_eq!(summary["tasks"]["completion"]["done_without_evidence"], 1);
        assert!(summary["attention"]
                .as_array()
                .unwrap()
                .iter()
                .any(|item| item["kind"] == "done_without_evidence"
                    && item["task_id"] == "task-raw"
                && item["reason"] == "no_run"));
    }

    /// Attached media URLs are short-lived capabilities and never expose storage keys.
    #[test]
    fn social_get_post_media_url_is_signed_and_storage_opaque() {
        std::env::remove_var("STORAGE_PUBLIC_URL");
        std::env::remove_var("STORAGE_ENDPOINT");
        std::env::remove_var("STORAGE_BUCKET");

        let db = test_db();
        let profile = db.social_create_profile("clerk_media_url", "mediaurl", "Media URL", "");
        let profile_id = profile["id"].as_str().unwrap();
        let media =
            db.social_create_media_object(profile_id, "pic.jpg", "image/jpeg", 100, "image");
        let media_id = media["id"].as_str().unwrap();
        let storage_key = media["storageKey"].as_str().unwrap();
        let _ = db.social_finalize_media_object(media_id);

        let post = db.social_create_post(
            profile_id,
            "with image",
            "public",
            "person",
            None,
            None,
            None,
            None,
        );
        let post_id = post["id"].as_str().unwrap();
        let linked = db.social_link_media_to_post(post_id, &[media_id.to_string()], profile_id);
        assert!(!linked.is_empty(), "media should link to post");

        let got = db.social_get_post_media(post_id, Some(profile_id));
        assert_eq!(got.len(), 1);
        let url = got[0]["url"].as_str().expect("url field");
        assert!(
            url.starts_with(&format!("/v1/social/media/{media_id}/content?")),
            "expected signed delivery route, got {url}"
        );
        assert!(
            !url.contains(storage_key),
            "url must not expose storage key, got {url}"
        );
    }

    /// Golden path: profile → post → feed → like → reply (real SQLite social tables).
    #[test]
    fn social_golden_path_profile_post_feed_like_reply() {
        let db = test_db();
        let profile = db.social_create_profile("clerk_user_a", "alice", "Alice", "hello");
        let profile_id = profile["id"].as_str().expect("profile id");
        assert_eq!(profile["handle"], "alice");

        let post = db.social_create_post(
            profile_id,
            "Hello HeyVera network",
            "public",
            "person",
            None,
            None,
            None,
            None,
        );
        let post_id = post["id"].as_str().expect("post id").to_string();
        assert_eq!(post["body"], "Hello HeyVera network");

        let bob = db.social_create_profile("clerk_user_b", "bob", "Bob", "");
        let bob_id = bob["id"].as_str().expect("bob id");

        db.social_like(bob_id, &post_id);
        assert!(db.social_get_follow_status(bob_id, profile_id) == false);
        db.social_follow(bob_id, profile_id);
        assert!(db.social_get_follow_status(bob_id, profile_id));

        let reply = db.social_create_post(
            bob_id,
            "Nice post",
            "public",
            "person",
            None,
            Some(&post_id),
            None,
            None,
        );
        assert_eq!(reply["replyToPostId"].as_str(), Some(post_id.as_str()));

        let mut feed = db.social_list_feed_posts_keyset(20, None, None, None, &[], &[]);
        db.social_enrich_feed_posts(&mut feed, Some(bob_id));
        assert!(
            feed.iter().any(|p| p["id"] == post_id),
            "home feed should include the new post"
        );

        let draft = db.pulse_create_draft(profile_id, "Draft body", "public", "person", None);
        let draft_id = draft["id"].as_str().expect("draft id");
        assert_eq!(draft["status"], "pending");
        let approved = db
            .pulse_update_draft_status(draft_id, profile_id, "approved")
            .expect("approve");
        assert_eq!(approved["status"], "approved");
    }

    /// Quote fidelity: enrich nests quoted post body/author for feed cards.
    #[test]
    fn social_enrich_feed_posts_nests_quote_post() {
        let db = test_db();
        let alice = db.social_create_profile("clerk_quote_a", "quotealice", "Alice", "");
        let bob = db.social_create_profile("clerk_quote_b", "quotebob", "Bob", "");
        let alice_id = alice["id"].as_str().unwrap();
        let bob_id = bob["id"].as_str().unwrap();

        let original = db.social_create_post(
            alice_id,
            "Original quotable body",
            "public",
            "person",
            None,
            None,
            None,
            None,
        );
        let original_id = original["id"].as_str().unwrap().to_string();

        let quote = db.social_create_post(
            bob_id,
            "Quoting you",
            "public",
            "person",
            None,
            None,
            Some(&original_id),
            None,
        );
        let quote_id = quote["id"].as_str().unwrap().to_string();
        assert_eq!(quote["quotePostId"].as_str(), Some(original_id.as_str()));

        let mut feed = db.social_list_feed_posts_keyset(20, None, None, None, &[], &[]);
        db.social_enrich_feed_posts(&mut feed, Some(bob_id));

        let quoted_row = feed
            .iter()
            .find(|p| p["id"] == quote_id)
            .expect("quote post in feed");
        assert_eq!(
            quoted_row["quotePostId"].as_str(),
            Some(original_id.as_str())
        );
        let nested = quoted_row
            .get("quotePost")
            .expect("enrich must nest quotePost");
        assert_eq!(nested["id"].as_str(), Some(original_id.as_str()));
        assert_eq!(nested["body"], "Original quotable body");
        assert_eq!(nested["author"]["handle"], "quotealice");
        assert_eq!(nested["author"]["displayName"], "Alice");
        assert!(nested["author"]["profileId"].as_str().is_some());

        // Single-post path also nests quotePost (thread root).
        let single = db
            .social_get_post_by_id(&quote_id, Some(bob_id))
            .expect("quote post by id");
        assert_eq!(
            single["quotePost"]["id"].as_str(),
            Some(original_id.as_str())
        );
        assert_eq!(single["quotePost"]["body"], "Original quotable body");
    }

    #[test]
    fn social_thread_replies_include_nested_descendants() {
        let db = test_db();
        let alice = db.social_create_profile("clerk_thread_a", "threada", "Alice", "");
        let bob = db.social_create_profile("clerk_thread_b", "threadb", "Bob", "");
        let carol = db.social_create_profile("clerk_thread_c", "threadc", "Carol", "");
        let alice_id = alice["id"].as_str().unwrap();
        let bob_id = bob["id"].as_str().unwrap();
        let carol_id = carol["id"].as_str().unwrap();

        let root =
            db.social_create_post(alice_id, "root", "public", "person", None, None, None, None);
        let root_id = root["id"].as_str().unwrap().to_string();
        let r1 = db.social_create_post(
            bob_id,
            "direct reply",
            "public",
            "person",
            None,
            Some(&root_id),
            None,
            None,
        );
        let r1_id = r1["id"].as_str().unwrap().to_string();
        let r2 = db.social_create_post(
            carol_id,
            "nested reply",
            "public",
            "person",
            None,
            Some(&r1_id),
            None,
            None,
        );
        let r2_id = r2["id"].as_str().unwrap().to_string();

        let (thread, truncated) = db.social_get_thread_replies(&root_id, None);
        assert_eq!(thread.len(), 2);
        assert!(!truncated, "small nested thread must not report truncation");
        let ids: Vec<&str> = thread.iter().filter_map(|p| p["id"].as_str()).collect();
        assert!(ids.contains(&r1_id.as_str()));
        assert!(ids.contains(&r2_id.as_str()));
        let nested = thread.iter().find(|p| p["id"] == r2_id).unwrap();
        assert_eq!(nested["replyToPostId"].as_str(), Some(r1_id.as_str()));
        assert_eq!(nested["body"], "nested reply");
        // camelCase shape for FE
        assert!(nested["author"]["profileId"].as_str().is_some());
        assert!(nested["createdAt"].as_str().is_some());
    }

    #[test]
    fn social_thread_replies_truncated_when_cap_hit() {
        let db = test_db();
        let author = db.social_create_profile("clerk_thread_cap", "threadcap", "Cap", "");
        let author_id = author["id"].as_str().unwrap();

        let root = db.social_create_post(
            author_id,
            "root many replies",
            "public",
            "person",
            None,
            None,
            None,
            None,
        );
        let root_id = root["id"].as_str().unwrap().to_string();

        // Cap is 100 — create 101 direct children so the walk stops early.
        for i in 0..101 {
            db.social_create_post(
                author_id,
                &format!("reply {i}"),
                "public",
                "person",
                None,
                Some(&root_id),
                None,
                None,
            );
        }

        let (thread, truncated) = db.social_get_thread_replies(&root_id, None);
        assert_eq!(thread.len(), 100, "must return at most the reply cap");
        assert!(truncated, "cap hit must set truncated true");
    }

    #[test]
    fn social_thread_replies_truncated_when_max_depth_blocks_frontier() {
        let db = test_db();
        let author = db.social_create_profile("clerk_thread_depth", "threaddepth", "Depth", "");
        let author_id = author["id"].as_str().unwrap();

        let root = db.social_create_post(
            author_id,
            "root deep",
            "public",
            "person",
            None,
            None,
            None,
            None,
        );
        let mut parent_id = root["id"].as_str().unwrap().to_string();

        // Max depth 8: create a chain of 9 replies so depth-9 is beyond the walk.
        for i in 0..9 {
            let child = db.social_create_post(
                author_id,
                &format!("depth {i}"),
                "public",
                "person",
                None,
                Some(&parent_id),
                None,
                None,
            );
            parent_id = child["id"].as_str().unwrap().to_string();
        }

        let (thread, truncated) = db.social_get_thread_replies(root["id"].as_str().unwrap(), None);
        assert_eq!(thread.len(), 8, "walk collects up to max depth 8");
        assert!(
            truncated,
            "remaining frontier blocked by max depth must set truncated"
        );
    }

